parameters.jsCode:
const input = $input.first().json || {};
const query = String(input.query || '').trim();
const namespace = String(input.namespace || '').trim();

if (!query) throw new Error('El parámetro query es obligatorio.');
if (!namespace) throw new Error('El parámetro namespace es obligatorio.');

const allowGeneralKnowledge = input.allowGeneralKnowledge === true || String(input.allowGeneralKnowledge).toLowerCase() === 'true';
const requestedMaxTokens = Number(input.maxTokens);

return [{
  json: {
    query: query.slice(0, 12000),
    namespace,
    allowGeneralKnowledge,
    maxTokens: Number.isFinite(requestedMaxTokens) && requestedMaxTokens > 0 ? Math.min(Math.floor(requestedMaxTokens), 4096) : 1024
  }
}];

const input = $('Preparar Entrada').first().json;
const rag = $input.first()?.json || {};
const context = String(rag.context || '').trim();
const noContextMarker = /no se encontr[oó] material relevante/i.test(context);
const hasContext = context.length > 0 && !noContextMarker;
const citations = Array.isArray(rag.citations) ? rag.citations : [];

const prompt = [
  `SOLICITUD DEL ESTUDIANTE:\n${input.query}`,
  hasContext
    ? `MATERIAL RECUPERADO DEL CURSO (fuente prioritaria):\n<course_material>\n${context}\n</course_material>`
    : 'No se recuperó material del curso para esta consulta.',
  input.allowGeneralKnowledge
    ? 'El coordinador permite complementar con conocimiento académico general. Si el material del curso es insuficiente, usa conocimiento general correcto y acláralo brevemente en la explicación.'
    : 'No uses conocimiento externo al material oficial del curso.'
].join('\n\n');

return [{
  json: {
    query: input.query,
    namespace: input.namespace,
    context,
    hasContext,
    citations,
    allowGeneralKnowledge: input.allowGeneralKnowledge,
    maxTokens: input.maxTokens,
    prompt
  }
}];

const input = $input.first()?.json || {};
const knowledge = $('Preparar Conocimiento').first().json;
const fail = (error) => [{ json: { success: false, error, citations: knowledge.citations || [], hasContext: knowledge.hasContext } }];

if (input.success === false) return fail(String(input.error || 'No se pudo generar el diagrama.'));

let result = input.output ?? input.answer ?? input;
if (typeof result === 'string') {
  const cleaned = result.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try {
    result = JSON.parse(cleaned);
  } catch {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (!match) return fail('El generador no devolvió una respuesta estructurada válida.');
    try { result = JSON.parse(match[0]); }
    catch { return fail('El generador no devolvió una respuesta estructurada válida.'); }
  }
}

if (!result || typeof result !== 'object' || Array.isArray(result)) return fail('El generador no devolvió un recurso válido.');
let graphic = String(result.graphic ?? result.mermaidCode ?? result.mermaid_code ?? '').trim();
graphic = graphic.replace(/^```(?:mermaid)?\s*/i, '').replace(/\s*```$/, '').trim();
if (!graphic) return fail('No se pudo crear un diagrama Mermaid para esta solicitud. Intenta describir el tema o el tipo de diagrama con más detalle.');
if (graphic.length > 16000) return fail('El diagrama generado es demasiado extenso. Intenta solicitar una versión más breve.');

const firstLine = graphic.split(/\r?\n/).map(line => line.trim()).find(line => line && !line.startsWith('%%')) || '';
const types = [
  [/^(?:flowchart|graph)\b/i, 'flowchart'],
  [/^mindmap\b/i, 'mindmap'],
  [/^sequencediagram\b/i, 'sequenceDiagram'],
  [/^statediagram(?:-v2)?\b/i, 'stateDiagram-v2'],
  [/^classdiagram\b/i, 'classDiagram'],
  [/^erdiagram\b/i, 'erDiagram'],
  [/^gantt\b/i, 'gantt'],
  [/^timeline\b/i, 'timeline'],
  [/^pie\b/i, 'pie'],
  [/^quadrantchart\b/i, 'quadrantChart'],
  [/^journey\b/i, 'journey'],
  [/^requirementdiagram\b/i, 'requirementDiagram'],
  [/^gitgraph\b/i, 'gitGraph'],
  [/^sankey-beta\b/i, 'sankey-beta'],
  [/^xychart-beta\b/i, 'xychart-beta'],
  [/^block-beta\b/i, 'block-beta'],
  [/^architecture-beta\b/i, 'architecture-beta'],
  [/^packet-beta\b/i, 'packet-beta'],
  [/^kanban\b/i, 'kanban'],
  [/^c4context\b/i, 'C4Context'],
  [/^c4container\b/i, 'C4Container']
];
const detected = types.find(([pattern]) => pattern.test(firstLine));
if (!detected) return fail('El generador devolvió un tipo Mermaid fuera del catálogo compatible.');

const title = String(result.title || 'Recurso académico').trim().slice(0, 160);
const explanation = String(result.explanation || '').trim().slice(0, 2000);
return [{ json: {
  success: true,
  title,
  explanation,
  graphic,
  diagramType: detected[1],
  citations: knowledge.citations || [],
  hasContext: knowledge.hasContext
} }];

const result = $input.first()?.json || {};
if (result.success === false) {
  return [{ json: { success: false, error: result.error || 'No se pudo generar el recurso.', citations: result.citations || [], hasContext: result.hasContext === true } }];
}
return [{ json: {
  success: true,
  title: result.title,
  explanation: result.explanation,
  graphic: result.graphic,
  diagramType: result.diagramType,
  citations: result.citations || [],
  hasContext: result.hasContext === true
} }];
